css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .62); height: var(--loader-size); border-radius: calc(var(--loader-size) * .3); background: linear-gradient(color-mix(in srgb, var(--accent) 14%, transparent), color-mix(in srgb, var(--accent-2) 14%, transparent)); position: relative; overflow: hidden; }
.loader span { position: absolute; left: 50%; width: calc(var(--loader-size) * .42); height: calc(var(--loader-size) * .42); margin-left: calc(var(--loader-size) * -.21); border-radius: 50%; background: radial-gradient(circle at 40% 35%, color-mix(in srgb, #fff 30%, var(--accent)), var(--accent)); animation: lava-a calc(var(--loader-speed) * 4) ease-in-out infinite; }
.loader span:nth-child(2) { width: calc(var(--loader-size) * .28); height: calc(var(--loader-size) * .28); margin-left: calc(var(--loader-size) * -.14); background: radial-gradient(circle at 40% 35%, color-mix(in srgb, #fff 30%, var(--accent-2)), var(--accent-2)); animation: lava-b calc(var(--loader-speed) * 5) ease-in-out infinite; }
@keyframes lava-a { 0%, 100% { bottom: -14%; border-radius: 50% 50% 44% 46%; } 50% { bottom: 76%; border-radius: 46% 44% 50% 48%; } }
@keyframes lava-b { 0%, 100% { bottom: 72%; } 50% { bottom: -10%; } }
